export type CubeFaceDirection = 'front' | 'back' | 'top' | 'bottom' | 'left' | 'right';

export interface RotationAngles {
  x: number;
  y: number;
  z?: number;
}

export interface CubeConfig {
  color: string;
  wireframe: boolean;
  autoRotate: boolean;
  rotationSpeed: number;
  roughness: number;
  metalness: number;
}

export interface CubeCanvasProps {
  config: CubeConfig;
  onResetRotation?: () => void;
}

export interface ControlPanelProps {
  config: CubeConfig;
  onChangeConfig: (newConfig: Partial<CubeConfig>) => void;
  onResetView: () => void;
}

export interface ColorOption {
  name: string;
  value: string;
}

export const PRESET_COLORS: ColorOption[] = [
  { name: 'シアン', value: '#38bdf8' },
  { name: 'エメラルド', value: '#10b981' },
  { name: 'ローズ', value: '#f43f5e' },
  { name: 'アンバー', value: '#f59e0b' },
  { name: 'バイオレット', value: '#8b5cf6' },
  { name: 'ホワイト', value: '#f8fafc' },
];

export const DEFAULT_CUBE_CONFIG: CubeConfig = {
  color: '#38bdf8',
  wireframe: false,
  autoRotate: true,
  rotationSpeed: 1.0,
  roughness: 0.3,
  metalness: 0.2,
};

:root {
  --bg-primary: #0f172a;
  --bg-secondary: #1e293b;
  --bg-card: rgba(30, 41, 59, 0.85);
  --bg-card-border: rgba(255, 255, 255, 0.08);
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --accent-cyan: #38bdf8;
  --accent-blue: #3b82f6;
  --accent-hover: #60a5fa;
  --btn-bg: #334155;
  --btn-bg-hover: #475569;
  --btn-active: #2563eb;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-panel: 0 10px 25px -5px rgba(0, 0, 0, 0.4), 0 8px 10px -6px rgba(0, 0, 0, 0.3);
  --shadow-btn: 0 4px 6px -1px rgba(0, 0, 0, 0.2);
  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-primary);
  color: var(--text-main);
  overflow-x: hidden;
  min-height: 100vh;
  line-height: 1.5;
}

/* メインコンテナ */
.app-container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  position: relative;
  background: radial-gradient(circle at 50% 20%, #1e293b 0%, #0f172a 100%);
}

/* ヘッダー */
.header-bar {
  padding: 16px 24px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  background-color: rgba(15, 23, 42, 0.8);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--bg-card-border);
  z-index: 10;
}

.header-title {
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  color: #ffffff;
  display: flex;
  align-items: center;
  gap: 8px;
}

.header-subtitle {
  font-size: 0.85rem;
  color: var(--text-muted);
}

/* 3Dキャンバスコンテナ */
.canvas-container {
  flex: 1;
  width: 100%;
  height: calc(100vh - 120px);
  position: relative;
  touch-action: none;
  cursor: grab;
  user-select: none;
}

.canvas-container:active {
  cursor: grabbing;
}

.canvas-container canvas {
  width: 100% !important;
  height: 100% !important;
  display: block;
}

/* 操作案内オーバーレイ */
.overlay-instructions {
  position: absolute;
  top: 16px;
  left: 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 14px;
  background-color: rgba(15, 23, 42, 0.65);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border-radius: var(--radius-md);
  border: 1px solid var(--bg-card-border);
  font-size: 0.78rem;
  color: var(--text-muted);
  pointer-events: none;
  z-index: 5;
}

.overlay-instructions span {
  display: flex;
  align-items: center;
  gap: 6px;
}

/* コントロールパネル */
.control-panel {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 310px;
  max-width: calc(100vw - 32px);
  max-height: calc(100% - 32px);
  overflow-y: auto;
  background-color: var(--bg-card);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--bg-card-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-panel);
  display: flex;
  flex-direction: column;
  gap: 18px;
  z-index: 20;
}

.panel-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.panel-label {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
}

/* カラーパレット */
.color-palette {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 8px;
}

.color-chip {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--radius-sm);
  border: 2px solid transparent;
  cursor: pointer;
  transition: transform 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
  padding: 0;
  outline: none;
}

.color-chip:hover {
  transform: scale(1.08);
}

.color-chip-active {
  border-color: #ffffff;
  box-shadow: 0 0 10px rgba(255, 255, 255, 0.4);
  transform: scale(1.1);
}

/* スライダー操作 */
.slider-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.slider-label-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  color: var(--text-main);
}

.slider-input {
  width: 100%;
  height: 6px;
  -webkit-appearance: none;
  appearance: none;
  background: var(--btn-bg);
  border-radius: 3px;
  outline: none;
  cursor: pointer;
}

.slider-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--accent-cyan);
  cursor: pointer;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.6);
  transition: transform 0.15s ease;
}

.slider-input::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

.slider-input::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--accent-cyan);
  cursor: pointer;
  border: none;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.6);
  transition: transform 0.15s ease;
}

.slider-input::-moz-range-thumb:hover {
  transform: scale(1.2);
}

/* トグルボタン・スイッチ */
.toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.toggle-button {
  background-color: var(--btn-bg);
  color: var(--text-muted);
  border: 1px solid var(--bg-card-border);
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.82rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  flex: 1;
  text-align: center;
}

.toggle-button:hover {
  background-color: var(--btn-bg-hover);
  color: var(--text-main);
}

.toggle-button-active {
  background-color: var(--btn-active);
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.2);
  box-shadow: 0 0 12px rgba(37, 99, 235, 0.4);
}

/* アクションボタン */
.action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 16px;
  background-color: var(--btn-bg);
  color: var(--text-main);
  border: 1px solid var(--bg-card-border);
  border-radius: var(--radius-md);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: var(--shadow-btn);
}

.action-btn:hover {
  background-color: var(--btn-bg-hover);
}

.action-btn:active {
  transform: scale(0.98);
}

.reset-btn {
  background-color: rgba(239, 68, 68, 0.15);
  color: #fca5a5;
  border: 1px solid rgba(239, 68, 68, 0.3);
}

.reset-btn:hover {
  background-color: rgba(239, 68, 68, 0.25);
  color: #ffffff;
}

/* バッジ表示 */
.badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 9999px;
  font-size: 0.72rem;
  font-weight: 600;
  background-color: rgba(56, 189, 248, 0.15);
  color: var(--accent-cyan);
  border: 1px solid rgba(56, 189, 248, 0.25);
}

/* フッター情報 */
.footer-info {
  padding: 10px 24px;
  background-color: rgba(15, 23, 42, 0.9);
  border-top: 1px solid var(--bg-card-border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.75rem;
  color: var(--text-muted);
  z-index: 10;
}

/* レスポンシブ対応 (スマートフォン・幅小画面向け) */
@media (max-width: 768px) {
  .app-container {
    height: 100vh;
    overflow: hidden;
  }

  .canvas-container {
    height: 100%;
  }

  .overlay-instructions {
    top: 8px;
    left: 8px;
    padding: 6px 10px;
    font-size: 0.72rem;
  }

  .control-panel {
    position: fixed;
    top: auto;
    bottom: 0;
    left: 0;
    right: 0;
    width: 100%;
    max-width: 100%;
    max-height: 48vh;
    border-radius: var(--radius-lg) var(--radius-lg) 0 0;
    padding: 16px;
    gap: 14px;
    background-color: rgba(15, 23, 42, 0.95);
  }

  .footer-info {
    display: none;
  }
}

import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { CubeCanvasProps } from '../types';

const CubeCanvas = ({ config, onResetRotation }: CubeCanvasProps) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  // Three.js インスタンスの参照保持
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const meshRef = useRef<THREE.Mesh<THREE.BoxGeometry, THREE.MeshStandardMaterial> | null>(null);
  const edgesRef = useRef<THREE.LineSegments | null>(null);

  // ドラッグ・操作および慣性用の状態参照
  const isDraggingRef = useRef(false);
  const previousPointerPosRef = useRef({ x: 0, y: 0 });
  const velocityRef = useRef({ x: 0, y: 0 });
  const targetRotationRef = useRef({ x: 0.4, y: 0.6 });
  const currentRotationRef = useRef({ x: 0.4, y: 0.6 });
  const cameraDistanceRef = useRef(4.5);
  const configRef = useRef(config);

  // 最新のconfigを参照に同期
  useEffect(() => {
    configRef.current = config;
  }, [config]);

  // マテリアル設定の動的反映
  useEffect(() => {
    if (!meshRef.current) return;

    const material = meshRef.current.material;
    material.color.set(config.color);
    material.wireframe = config.wireframe;
    material.roughness = config.roughness;
    material.metalness = config.metalness;
    material.needsUpdate = true;

    if (edgesRef.current) {
      edgesRef.current.visible = !config.wireframe;
    }
  }, [config.color, config.wireframe, config.roughness, config.metalness]);

  // Three.js シーン初期化
  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;

    const width = container.clientWidth || window.innerWidth;
    const height = container.clientHeight || window.innerHeight;

    // シーン作成
    const scene = new THREE.Scene();
    sceneRef.current = scene;

    // カメラ作成
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 100);
    camera.position.set(0, 0, cameraDistanceRef.current);
    cameraRef.current = camera;

    // レンダラー初期化
    const renderer = new THREE.WebGLRenderer({
      canvas,
      alpha: true,
      antialias: true,
      powerPreference: 'high-performance',
    });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    rendererRef.current = renderer;

    // 照明の追加
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.7);
    scene.add(ambientLight);

    const dirLight1 = new THREE.DirectionalLight(0xffffff, 1.8);
    dirLight1.position.set(5, 8, 5);
    dirLight1.castShadow = true;
    scene.add(dirLight1);

    const dirLight2 = new THREE.DirectionalLight(0x38bdf8, 0.8);
    dirLight2.position.set(-5, -4, -4);
    scene.add(dirLight2);

    const pointLight = new THREE.PointLight(0xffffff, 0.6, 10);
    pointLight.position.set(0, 2, 3);
    scene.add(pointLight);

    // 立方体メッシュ作成
    const geometry = new THREE.BoxGeometry(2, 2, 2);
    const material = new THREE.MeshStandardMaterial({
      color: configRef.current.color,
      roughness: configRef.current.roughness,
      metalness: configRef.current.metalness,
      wireframe: configRef.current.wireframe,
      flatShading: false,
    });

    const mesh = new THREE.Mesh(geometry, material);
    mesh.rotation.x = currentRotationRef.current.x;
    mesh.rotation.y = currentRotationRef.current.y;
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    scene.add(mesh);
    meshRef.current = mesh;

    // 面のエッジライン
    const edgesGeometry = new THREE.EdgesGeometry(geometry);
    const edgesMaterial = new THREE.LineBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0.25,
    });
    const edges = new THREE.LineSegments(edgesGeometry, edgesMaterial);
    edges.visible = !configRef.current.wireframe;
    mesh.add(edges);
    edgesRef.current = edges;

    // アニメーションループ
    let animationFrameId: number;
    let lastTime = performance.now();

    const animate = (currentTime: number) => {
      animationFrameId = requestAnimationFrame(animate);

      const delta = (currentTime - lastTime) / 1000;
      lastTime = currentTime;

      const currentConfig = configRef.current;

      // 自動回転
      if (currentConfig.autoRotate && !isDraggingRef.current) {
        const speed = currentConfig.rotationSpeed * 0.45 * delta;
        targetRotationRef.current.y += speed;
        targetRotationRef.current.x += speed * 0.4;
      }

      // 慣性の減衰処理
      if (!isDraggingRef.current) {
        targetRotationRef.current.x += velocityRef.current.x;
        targetRotationRef.current.y += velocityRef.current.y;
        velocityRef.current.x *= 0.92;
        velocityRef.current.y *= 0.92;
      }

      // スムーズな補間 (LERP)
      const lerpFactor = 0.12;
      currentRotationRef.current.x += (targetRotationRef.current.x - currentRotationRef.current.x) * lerpFactor;
      currentRotationRef.current.y += (targetRotationRef.current.y - currentRotationRef.current.y) * lerpFactor;

      if (meshRef.current) {
        meshRef.current.rotation.x = currentRotationRef.current.x;
        meshRef.current.rotation.y = currentRotationRef.current.y;
      }

      // カメラズーム補間
      if (cameraRef.current) {
        cameraRef.current.position.z += (cameraDistanceRef.current - cameraRef.current.position.z) * 0.1;
      }

      renderer.render(scene, camera);
    };

    animationFrameId = requestAnimationFrame(animate);

    // リサイズハンドラ
    const handleResize = () => {
      if (!container || !renderer || !camera) return;
      const newWidth = container.clientWidth;
      const newHeight = container.clientHeight;
      camera.aspect = newWidth / newHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(newWidth, newHeight);
    };

    window.addEventListener('resize', handleResize);

    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener('resize', handleResize);
      geometry.dispose();
      material.dispose();
      edgesGeometry.dispose();
      edgesMaterial.dispose();
      renderer.dispose();
    };
  }, []);

  // ポインタードラッグ回転イベント処理
  const handlePointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    isDraggingRef.current = true;
    previousPointerPosRef.current = { x: event.clientX, y: event.clientY };
    velocityRef.current = { x: 0, y: 0 };
    (event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);
  };

  const handlePointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    if (!isDraggingRef.current) return;

    const deltaX = event.clientX - previousPointerPosRef.current.x;
    const deltaY = event.clientY - previousPointerPosRef.current.y;

    const rotationFactor = 0.007;
    const rotY = deltaX * rotationFactor;
    const rotX = deltaY * rotationFactor;

    targetRotationRef.current.y += rotY;
    targetRotationRef.current.x += rotX;

    velocityRef.current = {
      x: rotX * 0.6,
      y: rotY * 0.6,
    };

    previousPointerPosRef.current = { x: event.clientX, y: event.clientY };
  };

  const handlePointerUp = (event: React.PointerEvent<HTMLDivElement>) => {
    isDraggingRef.current = false;
    try {
      (event.currentTarget as HTMLElement).releasePointerCapture(event.pointerId);
    } catch {
      // ポインタキャプチャ解除の安全策
    }
  };

  // ホイールによるカメラズーム
  const handleWheel = (event: React.WheelEvent<HTMLDivElement>) => {
    event.preventDefault();
    const zoomDelta = event.deltaY * 0.003;
    cameraDistanceRef.current = Math.min(Math.max(cameraDistanceRef.current + zoomDelta, 2.5), 8.0);
  };

  // 親からの回転リセット呼び出しに対応
  useEffect(() => {
    if (onResetRotation) {
      targetRotationRef.current = { x: 0.4, y: 0.6 };
      velocityRef.current = { x: 0, y: 0 };
      cameraDistanceRef.current = 4.5;
    }
  }, [onResetRotation]);

  return (
    <div
      ref={containerRef}
      className="canvas-container"
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerUp}
      onWheel={handleWheel}
    >
      <canvas ref={canvasRef} />
    </div>
  );
};

export default CubeCanvas;

import { useState, useCallback } from 'react';
import {
  Rotate3d,
  Play,
  Pause,
  RotateCcw,
  Sparkles,
  Sliders,
  Move,
  ZoomIn,
} from 'lucide-react';
import CubeCanvas from './components/CubeCanvas';
import {
  CubeConfig,
  DEFAULT_CUBE_CONFIG,
  PRESET_COLORS,
} from './types';

const App = () => {
  const [config, setConfig] = useState<CubeConfig>(DEFAULT_CUBE_CONFIG);
  const [resetKey, setResetKey] = useState<number>(0);

  // 設定更新ハンドラ
  const handleConfigChange = useCallback((patch: Partial<CubeConfig>) => {
    setConfig((prev) => ({ ...prev, ...patch }));
  }, []);

  // 視点および設定のリセット
  const handleResetView = useCallback(() => {
    setResetKey((prev) => prev + 1);
    setConfig((prev) => ({
      ...prev,
      autoRotate: false,
    }));
  }, []);

  // 全ての設定を初期値に戻す
  const handleResetAll = useCallback(() => {
    setResetKey((prev) => prev + 1);
    setConfig(DEFAULT_CUBE_CONFIG);
  }, []);

  return (
    <div className="app-container">
      {/* ヘッダー */}
      <header className="header-bar">
        <div className="header-title">
          <Rotate3d size={22} className="header-icon" />
          <span>インタラクティブ 3D キューブ</span>
          <span className="badge">WebGL Studio</span>
        </div>
        <p className="header-subtitle">
          ドラッグで回転、ホイールでズーム、各種マテリアル属性をリアルタイム制御
        </p>
      </header>

      {/* 3Dキャンバス領域 */}
      <main style={{ position: 'relative', flex: 1, display: 'flex' }}>
        <CubeCanvas
          config={config}
          onResetRotation={resetKey > 0 ? handleResetView : undefined}
        />

        {/* 操作方法オーバーレイ */}
        <div className="overlay-instructions">
          <span>
            <Move size={14} /> 左ボタンドラッグ / スワイプ: 3D回転
          </span>
          <span>
            <ZoomIn size={14} /> マウスホイール / ピンチ: 拡大・縮小
          </span>
          <span>
            <Sparkles size={14} /> 放すと滑らかな慣性回転
          </span>
        </div>

        {/* コントロールパネル */}
        <aside className="control-panel">
          {/* カラー選択パレット */}
          <section className="panel-section">
            <span className="panel-label">マテリアルカラー</span>
            <div className="color-palette">
              {PRESET_COLORS.map((color) => {
                const isActive = config.color === color.value;
                return (
                  <button
                    key={color.value}
                    type="button"
                    title={color.name}
                    className={`color-chip ${isActive ? 'color-chip-active' : ''}`}
                    style={{ backgroundColor: color.value }}
                    onClick={() => handleConfigChange({ color: color.value })}
                    aria-label={color.name}
                  />
                );
              })}
            </div>
          </section>

          {/* 表示モード切り替え */}
          <section className="panel-section">
            <span className="panel-label">レンダリングスタイル</span>
            <div className="toggle-row">
              <button
                type="button"
                className={`toggle-button ${!config.wireframe ? 'toggle-button-active' : ''}`}
                onClick={() => handleConfigChange({ wireframe: false })}
              >
                ソリッド
              </button>
              <button
                type="button"
                className={`toggle-button ${config.wireframe ? 'toggle-button-active' : ''}`}
                onClick={() => handleConfigChange({ wireframe: true })}
              >
                ワイヤーフレーム
              </button>
            </div>
          </section>

          {/* 自動回転切り替え */}
          <section className="panel-section">
            <span className="panel-label">アニメーション</span>
            <div className="toggle-row">
              <button
                type="button"
                className={`toggle-button ${config.autoRotate ? 'toggle-button-active' : ''}`}
                onClick={() => handleConfigChange({ autoRotate: !config.autoRotate })}
                style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: '6px' }}
              >
                {config.autoRotate ? <Pause size={14} /> : <Play size={14} />}
                {config.autoRotate ? '自動回転: オン' : '自動回転: 一時停止'}
              </button>
            </div>
          </section>

          {/* 回転速度 */}
          <section className="panel-section">
            <div className="slider-group">
              <div className="slider-label-row">
                <span>回転スピード</span>
                <span>{config.rotationSpeed.toFixed(1)}x</span>
              </div>
              <input
                type="range"
                className="slider-input"
                min="0.2"
                max="3.0"
                step="0.1"
                value={config.rotationSpeed}
                onChange={(e) =>
                  handleConfigChange({ rotationSpeed: parseFloat(e.target.value) })
                }
              />
            </div>
          </section>

          {/* 質感パラメータ（粗さ・金属感） */}
          <section className="panel-section">
            <span className="panel-label">
              <Sliders size={13} style={{ verticalAlign: 'middle', marginRight: 4 }} />
              物理マテリアルパラメータ
            </span>
            <div className="slider-group">
              <div className="slider-label-row">
                <span>表面の粗さ (Roughness)</span>
                <span>{Math.round(config.roughness * 100)}%</span>
              </div>
              <input
                type="range"
                className="slider-input"
                min="0"
                max="1"
                step="0.05"
                value={config.roughness}
                onChange={(e) =>
                  handleConfigChange({ roughness: parseFloat(e.target.value) })
                }
              />
            </div>

            <div className="slider-group" style={{ marginTop: '6px' }}>
              <div className="slider-label-row">
                <span>金属感 (Metalness)</span>
                <span>{Math.round(config.metalness * 100)}%</span>
              </div>
              <input
                type="range"
                className="slider-input"
                min="0"
                max="1"
                step="0.05"
                value={config.metalness}
                onChange={(e) =>
                  handleConfigChange({ metalness: parseFloat(e.target.value) })
                }
              />
            </div>
          </section>

          {/* アクションボタン */}
          <section className="panel-section" style={{ marginTop: '4px', gap: '10px' }}>
            <button
              type="button"
              className="action-btn"
              onClick={handleResetView}
            >
              <RotateCcw size={15} />
              視点をリセット
            </button>
            <button
              type="button"
              className="action-btn reset-btn"
              onClick={handleResetAll}
            >
              全設定を初期化
            </button>
          </section>
        </aside>
      </main>

      {/* フッター情報 */}
      <footer className="footer-info">
        <span>Three.js + React 3D Cube Controller</span>
        <span>カラー: {config.color.toUpperCase()} | 粗さ: {config.roughness} | 金属度: {config.metalness}</span>
      </footer>
    </div>
  );
};

export default App;
